'use server'

import { revalidatePath } from 'next/cache'

let notificationsEnabled = false

export async function getNotificationPreference(): Promise<boolean> {
  return notificationsEnabled
}

export async function toggleNotificationPreference(): Promise<{ success: boolean }> {
  notificationsEnabled = !notificationsEnabled

  revalidatePath('/')

  return { success: true }
}

'use client'

import { useEffect, useState, useTransition } from 'react'
import { getNotificationPreference, toggleNotificationPreference } from './actions'

interface NotificationToggleProps {
  initialValue: boolean
}

export function NotificationToggle({ initialValue }: NotificationToggleProps) {
  const [isPending, startTransition] = useTransition()
  const [enabled, setEnabled] = useState(initialValue)
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
    getNotificationPreference().then(setEnabled)
  }, [])

  const handleToggle = () => {
    startTransition(async () => {
      await toggleNotificationPreference()
    })
  }

  if (!mounted) {
    return <div className="toggle-skeleton">Loading...</div>
  }

  return (
    <button
      onClick={handleToggle}
      disabled={isPending}
      style={{
        padding: '12px 24px',
        fontSize: '16px',
        borderRadius: '8px',
        border: 'none',
        backgroundColor: enabled ? '#22c55e' : '#6b7280',
        color: 'white',
        cursor: isPending ? 'wait' : 'pointer',
        transition: 'background-color 0.2s'
      }}
    >
      {isPending ? 'Updating...' : enabled ? 'Notifications ON' : 'Notifications OFF'}
    </button>
  )
}

import { getNotificationPreference } from './actions'
import { NotificationToggle } from './NotificationToggle'

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference()

  return (
    <main style={{ padding: '40px', maxWidth: '600px', margin: '0 auto' }}>
      <h1 style={{ fontSize: '32px', marginBottom: '8px' }}>Settings</h1>
      <p style={{ color: '#666', marginBottom: '24px' }}>
        Manage your notification preferences
      </p>

      <div style={{ 
        padding: '24px', 
        border: '1px solid #e5e7eb', 
        borderRadius: '12px',
        backgroundColor: '#f9fafb'
      }}>
        <h2 style={{ fontSize: '18px', marginBottom: '16px' }}>Email Notifications</h2>
        <NotificationToggle initialValue={notificationsEnabled} />
      </div>
    </main>
  )
}
